function patternToRegex(pattern: string) {
  const escaped = pattern
    .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
    .replace(/\\\[\.\.\.([A-Za-z0-9_]+)\\\]/g, "(.+)")
    .replace(/\\\[([A-Za-z0-9_]+)\\\]/g, "([^/]+)");
  return new RegExp("^" + escaped + "$");
}

const KNOWN_DYNAMIC_APP_ROUTE_REGEX = KNOWN_DYNAMIC_APP_ROUTE_PATTERNS.map(patternToRegex);

export function isKnownAppRoute(path: string) {
  if (KNOWN_STATIC_APP_ROUTES.has(path)) return true;
  return KNOWN_DYNAMIC_APP_ROUTE_REGEX.some((regex) => regex.test(path));
}
